    <div class=\"sep\"></div>
    <label style=\"color:var(--muted);font-size:13px\">Preset
      <select id=\"preset\">
        <option value=\"\">— none —</option>
        <option value=\"glider\">Glider</option>
        <option value=\"gun\">Gosper Gun</option>
        <option value=\"pulsar\">Pulsar</option>
        <option value=\"lwss\">LWSS</option>
      </select>
    </label>
    <div class=\"sep\"></div>
    <label style=\"color:var(--muted);font-size:13px\">Speed
      <input type=\"range\" id=\"speed\" min=\"1\" max=\"60\" value=\"12\">
    </label>
  </div>

