    <span>Generation <b id=\"gen\">0</b></span>
    <span>Population <b id=\"pop\">0</b></span>
    <span>Grid <b id=\"gridsize\"></b></span>
    <span><span class=\"dot alive\"></span>draw · <span class=\"dot dead\"></span>erase</span>
