(() => {
  // ---- grid definition ----
  const ROWS = 60, COLS = 90, CELL = 9;
  let grid = new Uint8Array(ROWS * COLS);

  const board = document.getElementById('board');
  const cells = new Array(ROWS * COLS);
  board.style.gridTemplateColumns = "'`repeat(${COLS}, ${CELL}px)`;
  board.style.gridTemplateRows = `repeat(${ROWS}, ${CELL}px)`;

  for (let i = 0; i < ROWS * COLS; i++) {
    const d = document.createElement('"'div');
    d.className = 'cell';
    d.dataset.i = i;
    board.appendChild(d);
    cells[i] = d;
  }
  document.getElementById('gridsize').textContent = "'`${ROWS}×${COLS}`;

  // ---- DOM ----
  const playBtn = document.getElementById('"'play');
  const speed = document.getElementById('speed');
  const genEl = document.getElementById('gen');
  const popEl = document.getElementById('pop');
  const presetSel = document.getElementById('preset');

  let running = false;
  let timer = null;
  let generation = 0;

  // ---- state helpers ----
  const idx = (r, c) => ((r + ROWS) % ROWS) * COLS + ((c + COLS) % COLS);

  function neighbors(r, c) {
    let n = 0;
    n += grid[idx(r-1, c-1)]; n += grid[idx(r-1, c)]; n += grid[idx(r-1, c+1)];
    n += grid[idx(r,   c-1)];                         n += grid[idx(r,   c+1)];
    n += grid[idx(r+1, c-1)]; n += grid[idx(r+1, c)]; n += grid[idx(r+1, c+1)];
