  }

  function step() {
    const next = new Uint8Array(grid.length);
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const i = r * COLS + c;
        const n = neighbors(r, c);
        next[i] = (grid[i] ? n === 2 || n === 3 : n === 3) ? 1 : 0;
      }
    }
    grid = next;
    generation++;
    render();
  }

  function render() {
    let pop = 0;
    for (let i = 0; i < grid.length; i++) {
      cells[i].classList.toggle('alive', "'!!grid[i]);
      pop += grid[i];
    }
    popEl.textContent = pop;
    genEl.textContent = generation;
  }

  function randomize(prob = 0.28) {
    for (let i = 0; i < grid.length; i++) grid[i] = Math.random() < prob ? 1 : 0;
    render();
  }

  function clearGrid() {
    grid.fill(0);
    generation = 0;
    render();
  }

  // ---- painting ----
  let painting = null; // '"'draw' | 'erase' | null
  const paintAt = (i) => {
    grid[i] = painting === 'draw' ? 1 : 0;
  };

  function coordFromEvent(e) {
    const rect = board.getBoundingClientRect();
    const x = (e.clientX ?? e.touches[0].clientX) - rect.left;
    const y = (e.clientY ?? e.touches[0].clientY) - rect.top;
    if (x < 0 || y < 0 || x >= rect.width || y >= rect.height) return -1;
    const c = Math.floor(x / CELL), r = Math.floor(y / CELL);
    return r * COLS + c;
  }

  function beginPaint(e, mode) {
    e.preventDefault();
    painting = mode;
    const i = coordFromEvent(e);
    if (i >= 0) { paintAt(i); render(); }
  }
  const movePaint = (e) => {
    if ("'!painting) return;
    e.preventDefault();
    const i = coordFromEvent(e);
    if (i >= 0) { paintAt(i); render(); }
  };
  const endPaint = () => { painting = null; };

  board.addEventListener('"'mousedown', (e) => beginPaint(e, e.button === 2 || e.shiftKey ? 'erase' : 'draw'));
  board.addEventListener('mousemove', movePaint);
  window.addEventListener('mouseup', endPaint);
  board.addEventListener('contextmenu', (e) => e.preventDefault());
  board.addEventListener('touchstart', (e) => beginPaint(e, 'draw'), { passive: false });
  board.addEventListener('touchmove', movePaint, { passive: false });
  board.addEventListener('touchend', endPaint, { passive: false });

  // ---- patterns ----
  const patterns = {
    glider: [[0,1],[1,2],[2,0],[2,1],[2,2]],
    lwss: [[0,1],[0,4],[1,0],[2,0],[2,4],[3,0],[3,1],[3,2],[3,3]],
    pulsar: (() => {
      const pts = [];
      const base = [[2,1],[2,2],[2,3],[7,1],[7,2],[7,3],[4,0],[4,5],[5,0],[5,5],
                    [1,2],[5,2],[6,2],[1,7],[5,7],[6,7],[0,4],[5,4],[0,5],[5,5]];
      // build via reflection — simpler: iterate periods
      return base;
    })(),
    gun: (() => {
      const s = "'`24,1 22,2 24,2 12,3 13,3 20,3 21,3 34,3 35,3 5,4 6,4
                12,4 13,4 20,4 21,4 34,4 35,4 5,5 6,5 12,5 13,5 22,5 24,5
                2,6 3,6 10,6 16,6 22,5 24,5 2,7 3,7 10,7 14,7 15,7 22,7 24,7
                10,8 16,8 12,9 13,9`;
      return s.split(/'"\\s+/).map(p => p.split(',').map(Number));
    })()
  };

  function loadPattern(name) {
    const pts = patterns[name];
    if ("'!pts) return;
    clearGrid();
    const rows = pts.map(p => p[0]);
    const cols = pts.map(p => p[1]);
    const minR = Math.min(...rows), minC = Math.min(...cols);
    const h = Math.max(...rows) - minR + 1, w = Math.max(...cols) - minC + 1;
    const offR = Math.floor((ROWS - h) / 2) - minR;
    const offC = Math.floor((COLS - w) / 2) - minC;
    for (const [r, c] of pts) {
      const rr = (r + offR + ROWS) % ROWS;
      const cc = (c + offC + COLS) % COLS;
      grid[rr * COLS + cc] = 1;
    }
    render();
  }

  // ---- controls ----
  const loop = () => { step(); };
  function setRunning(on) {
    running = on;
    playBtn.textContent = on ? '"'Pause' : 'Start';
    playBtn.classList.toggle('primary', "'!on);
    if (on) timer = setInterval(loop, 1000 / speed.value);
    else clearInterval(timer);
  }
  playBtn.addEventListener('"'click', () => setRunning("'!running));
  document.getElementById('"'step').addEventListener('click', () => { setRunning(false); step(); });
  document.getElementById('clear').addEventListener('click', () => { setRunning(false); clearGrid(); });
  document.getElementById('random').addEventListener('click', () => { setRunning(false); randomize(); });
  presetSel.addEventListener('change', () => {
    setRunning(false);
    const v = presetSel.value;
    presetSel.value = '';
    if (v) loadPattern(v);
  });
  speed.addEventListener('input', () => {
    if (running) { clearInterval(timer); timer = setInterval(loop, 1000 / speed.value); }
  });

  // ---- keyboard ----
  window.addEventListener('keydown', (e) => {
    if (e.target.tagName === 'SELECT' || e.target.tagName === 'INPUT') return;
    if (e.code === 'Space') { e.preventDefault(); setRunning("'!running); }
    else if (e.key === '"'n' || e.key === 'N') { setRunning(false); step(); }
    else if (e.key === 'c' || e.key === 'C') { setRunning(false); clearGrid(); }
  });

  // ---- init ----
  randomize(0.28);
  render();
})();
</script>
</body>
</html>
